{
  "competitors": [
    {
      "name": "ServiceTitan",
      "slug": "servicetitan",
      "category": "direct",
      "description": "Enterprise-grade field service management platform covering scheduling, dispatch, CRM, marketing, and financing. The dominant platform for larger HVAC, plumbing, and electrical contractors. Known for deep feature set and high implementation complexity.",
      "key_differentiators": [
        "Largest feature set in the category (CRM, marketing automation, financing)",
        "Strong enterprise integrations and partner ecosystem",
        "High brand recognition and credibility with contractors",
        "Performance analytics and revenue intelligence tools"
      ],
      "why_included": "The market leader and most well-funded direct competitor. Investors will ask about it first. Targets the upper end of the SMB and lower enterprise segments — overlaps with Tessivane's market but at higher price and complexity."
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "Cloud-based field service management software targeting SMBs across residential and commercial trades. Covers scheduling, dispatch, quoting, invoicing, and client hub. More accessible than ServiceTitan with strong marketing presence.",
      "key_differentiators": [
        "Strong brand awareness among SMB tradespeople",
        "Intuitive UI with fast time to first value",
        "Client hub portal for homeowner communication",
        "Freemium trial model lowers acquisition friction"
      ],
      "why_included": "The most direct comparable competitor. Similar target market (SMB service businesses) and similar scope. Tessivane's primary benchmark for positioning on simplicity and price."
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "All-in-one field service management platform for home service pros. Focuses on SMB owner-operators in HVAC, plumbing, electrical, cleaning, and pest control. Includes scheduling, dispatch, payments, marketing, and financing (HCP Capital).",
      "key_differentiators": [
        "Embedded payments and financing (HCP Capital)",
        "Strong community and peer network for service pros",
        "Consumer-facing booking and review management",
        "Covers the full revenue cycle from lead to payment"
      ],
      "why_included": "Direct SMB-focused competitor with similar buyer profile to Tessivane. Has expanded aggressively into payments and financing, moving toward a broader SMB operating platform."
    }
  ],
  "candidate_axes": [
    {
      "id": "simplicity_vs_breadth",
      "x_axis": "Setup & operational complexity (low → high)",
      "y_axis": "Platform breadth beyond scheduling (narrow → broad)",
      "rationale": "Reveals the core trade-off in the SMB segment: buyers want tools they can use without a dedicated ops team, but also want breadth as they grow. Tessivane's simplicity thesis sits in the low-complexity, focused-scope quadrant — a deliberately different position from ServiceTitan's high-complexity, broad-platform stance. Competitors spread well across both axes."
    },
    {
      "id": "price_vs_automation",
      "x_axis": "Monthly price per technician (low → high)",
      "y_axis": "Dispatch automation depth (manual-assisted → intelligent/AI-driven)",
      "rationale": "Captures the cost-vs-capability tension that SMB buyers cite most often in reviews. A low-price, high-automation position would be Tessivane's ideal — if it can be evidenced. Competitors spread: ServiceTitan is high price and moderately automated; Jobber is mid-price with manual-assisted dispatch; Housecall Pro is mid-price with growing automation. Good differentiation potential."
    },
    {
      "id": "smb_fit_vs_scalability",
      "x_axis": "SMB-first design (enterprise-centric → SMB-native)",
      "y_axis": "Scalability ceiling (solo operator → multi-location enterprise)",
      "rationale": "Shows whether a tool was built for SMBs or adapted down from enterprise. Tessivane's core claim — SMB-first simplicity — maps directly to the SMB-native end of the x-axis. Competitors split: ServiceTitan is enterprise-centric, Jobber and Housecall Pro are in the middle, having started SMB-focused but growing up-market. Reveals Tessivane's strategic differentiation clearly."
    }
  ],
  "deck_competition_slide": {
    "present": false,
    "reason": "No pitch deck provided; founder described company and competitors in conversation."
  },
  "deck_competitors_excluded": [],
  "metadata": {
    "run_id": "cw-cp-smoke-0a1b2c3d"
  }
}
EOF
